<?php
declare(strict_types=1);namespace App\Controllers;
use App\Core\Database;use App\Core\Request;
final class ImportController extends BaseController {
 public function index(Request $r):void{$this->auth();$this->require('imports.manage');$this->view('imports/index',['flash'=>flash('success'),'error'=>flash('error')]);}
 public function upload(Request $r):void{$this->auth();$this->csrf();$this->require('imports.manage');$f=$r->files()['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK){flash('error','Please select a valid CSV file.');redirect('/imports');}$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['csv','xlsx','xls'],true)){flash('error','Allowed formats: CSV, XLSX, XLS.');redirect('/imports');}if($ext!=='csv'&&!class_exists(\PhpOffice\PhpSpreadsheet\IOFactory::class)){flash('error','Install Composer dependencies to import Excel files.');redirect('/imports');}$rows=[];try{if($ext==='csv'){$h=fopen($f['tmp_name'],'r');while(($row=fgetcsv($h))!==false)$rows[]=$row;fclose($h);}else{$book=\PhpOffice\PhpSpreadsheet\IOFactory::load($f['tmp_name']);$rows=$book->getActiveSheet()->toArray();}$headers=array_map(fn($x)=>strtolower(trim((string)$x)),array_shift($rows)??[]);$allowed=['vendor_code','legal_name','tax_registration_no','website','status','notes'];if(array_diff(['vendor_code','legal_name'],$headers))throw new \RuntimeException('Required columns: vendor_code, legal_name.');$pdo=Database::connection();$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO vendors(vendor_code,legal_name,tax_registration_no,website,status,notes) VALUES(?,?,?,?,?,?)');$ok=0;$bad=0;foreach($rows as $i=>$row){$d=array_combine($headers,array_pad(array_slice($row,0,count($headers)),count($headers),''));try{$s->execute([$d['vendor_code']??'', $d['legal_name']??'', $d['tax_registration_no']??null,$d['website']??null,$d['status']??'pending',$d['notes']??null]);$ok++;}catch(\Throwable){$bad++;}}$pdo->commit();\audit_log('bulk_import','vendors',null,null,['imported'=>$ok,'failed'=>$bad]);flash('success',"Import complete: {$ok} imported, {$bad} failed.");}catch(\Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error','Import failed: '.$e->getMessage());}redirect('/imports');}
}
